/* Token Radar — "night radar" theme. A deep slate canvas, one cyan signal colour, one amber highlight,
   and a warm red for negatives. Every size is a spacing token; the type scale is five steps. No
   network references: the two families are generic families resolved by the browser. */

:root {
  color-scheme: dark;

  --canvas: #0d1117;
  --canvas-2: #111823;
  --surface: #161d29;
  --surface-2: #1c2533;
  --ink: #e8eef7;
  --ink-2: #b3c0d1;
  --muted: #7d8ca1;
  --line: #26303f;
  --line-2: #323f52;

  --signal: #3fd0c9;
  --signal-dim: #1c6b66;
  --amber: #e9b449;
  --negative: #e0695f;
  --violet: #9d8cf0;

  --radius-sm: 7px;
  --radius: 11px;
  --radius-lg: 16px;

  --font-body: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", "JetBrains Mono", Menlo, Consolas, monospace;

  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
  --s8: 64px;

  --shadow: 0 18px 40px -24px rgba(0, 0, 0, 0.75);
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background:
    radial-gradient(1100px 520px at 8% -12%, rgba(63, 208, 201, 0.10), transparent 60%),
    radial-gradient(900px 480px at 100% 0%, rgba(157, 140, 240, 0.08), transparent 55%),
    var(--canvas);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
  text-wrap: pretty;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 { margin: 0; letter-spacing: -0.021em; text-wrap: balance; font-weight: 620; }
h1 { font-size: 30px; line-height: 1.12; }
h2 { font-size: 19px; line-height: 1.2; }
h3 { font-size: 13px; letter-spacing: 0.04em; text-transform: uppercase; color: var(--muted); }
p { margin: 0; }
a { color: var(--signal); text-decoration-color: color-mix(in srgb, var(--signal) 45%, transparent); }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }

:focus-visible { outline: 2px solid var(--signal); outline-offset: 2px; border-radius: 4px; }

.skip {
  position: absolute; left: -9999px; top: 0;
  padding: var(--s2) var(--s4); background: var(--surface-2);
  border: 1px solid var(--line-2); border-radius: var(--radius-sm); z-index: 40;
}
.skip:focus { left: var(--s4); top: var(--s4); }

.shell { max-width: 1340px; margin: 0 auto; padding: var(--s5) var(--s6) var(--s8); }

/* ---------------------------------------------------------------- masthead */

.masthead {
  display: flex; align-items: flex-end; justify-content: space-between;
  gap: var(--s5); flex-wrap: wrap;
  padding-bottom: var(--s4); border-bottom: 1px solid var(--line);
}
.wordmark { display: flex; align-items: center; gap: var(--s3); }
.pulse {
  width: 30px; height: 30px; flex: none; border-radius: 50%;
  display: grid; place-items: center;
  border: 1px solid var(--signal-dim);
  background: radial-gradient(circle at 50% 50%, rgba(63, 208, 201, 0.22), transparent 68%);
  position: relative;
}
.pulse::after {
  content: ""; width: 8px; height: 8px; border-radius: 50%;
  background: var(--signal); box-shadow: 0 0 12px 1px rgba(63, 208, 201, 0.9);
}
.wordmark b { font-size: 17px; letter-spacing: -0.01em; }
.wordmark span { color: var(--muted); font-size: 12px; font-family: var(--font-mono); }
.stamp { display: flex; flex-wrap: wrap; gap: var(--s3); justify-content: flex-end; }
.chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 10px; border: 1px solid var(--line); border-radius: 999px;
  background: var(--surface); color: var(--ink-2);
  font-family: var(--font-mono); font-size: 11.5px; letter-spacing: 0.01em; white-space: nowrap;
}
.chip em { font-style: normal; color: var(--muted); }
.chip.amber { border-color: color-mix(in srgb, var(--amber) 40%, var(--line)); color: var(--amber); }
.chip.signal { border-color: color-mix(in srgb, var(--signal) 42%, var(--line)); color: var(--signal); }

/* ---------------------------------------------------------------- headline */

.headline {
  display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(300px, 0.75fr);
  gap: var(--s7); padding: var(--s6) 0 var(--s5);
}
.headline .eyebrow {
  font-family: var(--font-mono); font-size: 11.5px; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--signal); margin-bottom: var(--s2);
}
.headline p.lede { color: var(--ink-2); max-width: 64ch; margin-top: var(--s3); }

.meters {
  display: grid; grid-template-columns: 1fr 1fr; gap: var(--s3);
  align-content: start;
}
.meter {
  background: linear-gradient(180deg, var(--surface), var(--canvas-2));
  border: 1px solid var(--line); border-radius: var(--radius); padding: var(--s3) var(--s4);
  display: grid; gap: 2px;
}
.meter .k { color: var(--muted); font-size: 11.5px; letter-spacing: 0.03em; text-transform: uppercase; }
.meter .v { font-family: var(--font-mono); font-size: 23px; font-weight: 500; letter-spacing: -0.02em; }
.meter .d { color: var(--muted); font-size: 11.5px; }
.meter.wide { grid-column: 1 / -1; grid-template-columns: auto 1fr; align-items: center; column-gap: var(--s4); }
.meter.wide .v { color: var(--amber); }

/* ---------------------------------------------------------------- controls */

.controls {
  display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--s3);
  padding: var(--s4) 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line);
}
.control { display: grid; gap: 5px; }
.control > label, .control > .lbl {
  color: var(--muted); font-size: 11px; letter-spacing: 0.09em; text-transform: uppercase;
}
.control input[type="search"], .control select {
  min-height: 38px; padding: 0 var(--s3);
  background: var(--surface); border: 1px solid var(--line-2); border-radius: var(--radius-sm);
  color: var(--ink);
}
.control input[type="search"] { min-width: 260px; }
.control input::placeholder { color: color-mix(in srgb, var(--muted) 80%, transparent); }

.segmented { display: inline-flex; gap: 2px; padding: 3px; background: var(--surface); border: 1px solid var(--line-2); border-radius: var(--radius-sm); }
.segmented button {
  min-height: 30px; padding: 0 var(--s3); border: 0; border-radius: 5px;
  background: transparent; color: var(--ink-2); white-space: nowrap;
}
.segmented button[aria-pressed="true"] { background: var(--signal); color: #04231f; font-weight: 600; }
.segmented button:not([aria-pressed="true"]):hover { background: var(--surface-2); color: var(--ink); }

.tally { margin-left: auto; align-self: center; color: var(--muted); font-size: 12.5px; font-family: var(--font-mono); }
.tally b { color: var(--ink); font-weight: 500; }

/* ---------------------------------------------------------------- table */

.panel {
  background: linear-gradient(180deg, var(--surface), var(--canvas-2));
  border: 1px solid var(--line); border-radius: var(--radius-lg);
  overflow: hidden; box-shadow: var(--shadow);
}
.table-scroll { overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
caption { text-align: left; padding: var(--s4) var(--s4) 0; color: var(--muted); font-size: 12px; }

thead th {
  position: sticky; top: 0; z-index: 2;
  background: var(--surface-2); color: var(--muted);
  font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; font-weight: 600;
  border-bottom: 1px solid var(--line-2);
  padding: 0;
  white-space: nowrap;
}
thead th .sort {
  display: flex; align-items: center; gap: 6px; width: 100%;
  min-height: 40px; padding: 0 var(--s3);
  border: 0; background: none; color: inherit; font: inherit; text-align: left;
}
thead th .sort:hover { color: var(--ink); background: color-mix(in srgb, var(--ink) 6%, transparent); }
thead th .sort[aria-sort] { color: var(--ink); }
thead th .caret { color: var(--signal); font-size: 10px; }
thead th.right .sort { justify-content: flex-end; }

tbody td { padding: var(--s3) var(--s3); border-bottom: 1px solid var(--line); vertical-align: middle; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: color-mix(in srgb, var(--signal) 6%, transparent); }
tbody tr[data-selected="true"] { background: color-mix(in srgb, var(--signal) 11%, transparent); }
tbody tr:last-child td { border-bottom: 0; }

.rank { font-family: var(--font-mono); color: var(--muted); }
.rank b { color: var(--ink); font-weight: 500; }
.proto { display: grid; gap: 1px; min-width: 190px; }
.proto b { font-weight: 600; }
.proto .sub { color: var(--muted); font-size: 11.5px; }
.num { font-family: var(--font-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
.right { text-align: right; }
.pos { color: var(--signal); }
.neg { color: var(--negative); }
.dim { color: var(--muted); }

.value-cell { display: flex; align-items: center; gap: var(--s2); justify-content: flex-end; }
.value-cell .meter-bar {
  width: min(120px, 16vw); height: 6px; border-radius: 999px; overflow: hidden;
  background: color-mix(in srgb, var(--line-2) 85%, transparent);
}
.value-cell .meter-bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--signal-dim), var(--signal)); }

.tag {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 3px 9px; border-radius: 999px; font-size: 11px; font-family: var(--font-mono);
  border: 1px solid var(--line-2); color: var(--ink-2); white-space: nowrap;
}
.tag::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.tag.pre { color: var(--amber); border-color: color-mix(in srgb, var(--amber) 35%, var(--line-2)); }
.tag.live { color: var(--violet); border-color: color-mix(in srgb, var(--violet) 35%, var(--line-2)); }
.tag.early { color: var(--signal); border-color: color-mix(in srgb, var(--signal) 35%, var(--line-2)); }

.empty { padding: var(--s8) var(--s5); display: grid; gap: var(--s3); justify-items: center; text-align: center; }
.empty p { color: var(--muted); }
.ghost {
  min-height: 38px; padding: 0 var(--s4); border-radius: var(--radius-sm);
  background: var(--surface-2); border: 1px solid var(--line-2); color: var(--ink);
}
.ghost.solid { background: var(--signal); border-color: var(--signal); color: #04231f; font-weight: 600; }

/* ---------------------------------------------------------------- formula note */

.note {
  margin-top: var(--s4); padding: var(--s5);
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-lg);
  display: grid; gap: var(--s3);
}
.note .formula {
  font-family: var(--font-mono); font-size: 12.5px; line-height: 1.75; color: var(--ink-2);
  overflow-wrap: anywhere;
  padding: var(--s3) var(--s4); background: var(--canvas); border: 1px solid var(--line);
  border-radius: var(--radius-sm);
}
.note .formula b { color: var(--signal); font-weight: 500; }
.note .formula .k { color: var(--amber); }
.note .fine { color: var(--muted); font-size: 12.5px; max-width: 100ch; }

/* ---------------------------------------------------------------- detail drawer */

.drawer {
  position: fixed; inset: 0 0 0 auto; z-index: 30;
  width: min(560px, 94vw); max-width: 100%;
  margin: 0; padding: 0; border: 0; border-left: 1px solid var(--line-2);
  background: var(--canvas-2);
  box-shadow: -30px 0 60px -30px rgba(0, 0, 0, 0.8);
  overflow-y: auto;
}
.drawer::backdrop { background: rgba(5, 8, 12, 0.62); backdrop-filter: blur(2px); }
.drawer[hidden] { display: none; }
.drawer-body { padding: var(--s5); display: grid; gap: var(--s5); }

.drawer-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s4); }
.drawer-head .sub { color: var(--muted); font-size: 12.5px; margin-top: var(--s1); }
.drawer-title { display: grid; gap: 4px; min-width: 0; }
.drawer-title .rankline { font-family: var(--font-mono); font-size: 12px; color: var(--signal); }
.drawer-title h2 { overflow-wrap: anywhere; }

.section { display: grid; gap: var(--s3); }
.section-head { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); border-top: 1px solid var(--line); padding-top: var(--s4); }

.figures { display: grid; gap: 0; }
.figure { display: flex; align-items: baseline; justify-content: space-between; gap: var(--s3); padding: 7px 0; border-bottom: 1px dashed var(--line); }
.figure:last-child { border-bottom: 0; }
.figure .k { color: var(--muted); font-size: 12.5px; }
.figure .v { font-family: var(--font-mono); font-size: 13px; }
.figure.hero { border-bottom: 1px solid var(--line-2); padding: var(--s3) 0; }
.figure.hero .k { font-size: 13px; }
.figure.hero .v { font-size: 22px; color: var(--amber); font-weight: 500; }

.steps { margin: 0; padding: 0; list-style: none; counter-reset: step; display: grid; gap: var(--s3); }
.steps li { counter-increment: step; display: grid; grid-template-columns: 26px 1fr; gap: var(--s3); }
.steps li::before {
  content: counter(step);
  display: grid; place-items: center; width: 26px; height: 26px;
  border-radius: 8px; border: 1px solid var(--signal-dim);
  background: color-mix(in srgb, var(--signal) 12%, transparent);
  color: var(--signal); font-family: var(--font-mono); font-size: 12px;
}
.steps .body { display: grid; gap: 4px; padding-top: 2px; }
.steps .body p { font-size: 13.5px; }
.steps .meta { display: flex; flex-wrap: wrap; gap: var(--s2); }
.steps .meta span {
  font-family: var(--font-mono); font-size: 11px; color: var(--muted);
  padding: 2px 8px; border: 1px solid var(--line); border-radius: 999px;
}
.steps .meta span.cost { color: var(--amber); border-color: color-mix(in srgb, var(--amber) 30%, var(--line)); }
.steps .meta span.time { color: var(--signal); border-color: color-mix(in srgb, var(--signal) 30%, var(--line)); }

.close {
  flex: none; width: 34px; height: 34px; border-radius: 50%;
  border: 1px solid var(--line-2); background: var(--surface); color: var(--ink-2);
  font-size: 15px; line-height: 1;
}
.close:hover { color: var(--ink); background: var(--surface-2); }

@media (max-width: 980px) {
  .shell { padding: var(--s4) var(--s4) var(--s7); }
  .headline { grid-template-columns: 1fr; gap: var(--s5); }
  .control input[type="search"] { min-width: 0; width: 100%; }
  .control { flex: 1 1 160px; }
}
@media (max-width: 560px) {
  .meters { grid-template-columns: 1fr; }
  .tally { width: 100%; margin-left: 0; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; animation-duration: 0.01ms !important; }
}
